        "condition": "...",
        "branches": []
      }
    ],
    "exceptions": [],
    "dependencies": [
      {
        "from": "A1",
        "to": "A2",
        "type": "control_flow"
      }
    ]
  },
  "automation_opportunities": [
    {
      "target": "activity or decision",
      "rationale": "...",
      "required_data": [],
      "constraints": [],
      "confidence": "low | medium | high"
    }
  ],
  "remaining_gaps": []
}

